client_script:
frappe.web_form.after_load = () => {
    if (window.location.pathname.endsWith("/new") && frappe.session.user) {
        let current_path = window.location.href;
        window.location.href = current_path.replace("/new", "/" + frappe.session.user);
    }
}

const detailFields = {
    custom_has_criminal_record: "custom_criminal_record_details",
    custom_has_non_disclosure_or_non_compete: "custom_non_disclosure_details"
};
function updateDetailVisibility(checkbox, value) {
    frappe.web_form.set_df_property(detailFields[checkbox], "hidden", Number(value) !== 1);
}
Object.keys(detailFields).forEach((checkbox) => {
    frappe.web_form.on(checkbox, (field, value) => updateDetailVisibility(checkbox, value));
});
frappe.web_form.after_load = () => {
    Object.keys(detailFields).forEach((checkbox) => {
        updateDetailVisibility(checkbox, frappe.web_form.get_value(checkbox));
    });
};
const applicationUploads = {
    custom_photo: [".png", ".jpg", ".jpeg", ".gif"],
    resume_attachment: [".pdf", ".doc", ".docx"]
};
Object.entries(applicationUploads).forEach(([fieldname, extensions]) => {
    const field = frappe.web_form.get_field(fieldname);
    field.on_attach_click = () => {
        const input = document.createElement("input");
        input.type = "file";
        input.accept = extensions.join(",");
        input.onchange = async () => {
            const file = input.files[0];
            if (!file) return;
            const extension = "." + file.name.split(".").pop().toLowerCase();
            if (!extensions.includes(extension)) {
                frappe.msgprint(__("Allowed file formats: {0}", [extensions.join(", ")]));
                return;
            }
            const data = new FormData();
            data.append("file", file);
            data.append("fieldname", fieldname);
            field.$input.prop("disabled", true);
            try {
                const response = await fetch("/api/method/administration.job_application.upload_application_file", {
                    method: "POST",
                    headers: {"X-Frappe-CSRF-Token": frappe.csrf_token || ""},
                    body: data
                });
                const result = await response.json();
                if (!response.ok || !result.message?.file_url) {
                    let message = __("Upload failed. Please check the file format and size and try again.");
                    if (result._server_messages) {
                        const messages = JSON.parse(result._server_messages);
                        message = messages.map((item) => JSON.parse(item).message).join("<br>");
                    }
                    frappe.msgprint(message);
                    return;
                }
                await field.on_upload_complete(result.message);
            } catch (error) {
                frappe.msgprint(__("Upload failed. Please try again."));
            } finally {
                field.$input.prop("disabled", false);
            }
        };
        input.click();
    };
});
